int countWords(const std::string& str) {
    std::string s = str;
    // Replace underscores with spaces
    std::replace(s.begin(), s.end(), '_', ' ');
    // Trim leading and trailing spaces
    size_t start = s.find_first_not_of(' ');
    size_t end = s.find_last_not_of(' ');
    if (start == std::string::npos || end == std::string::npos) {
        return 0;
    }
    s = s.substr(start, end - start + 1);
    // Replace multiple spaces with a single space
    std::string result;
    bool inSpace = false;
    for (char c : s) {
        if (isspace(c)) {
            if (!inSpace) {
                result += ' ';
                inSpace = true;
            }
        } else {
            result += c;
            inSpace = false;
        }
    }
    // Split by space
    int count = 0;
    size_t pos = 0;
    while ((pos = result.find(' ')) != std::string::npos) {
        if (!result.substr(0, pos).empty()) {
            count++;
        }
        result.erase(0, pos + 1);
    }
    if (!result.empty()) {
        count++;
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    std::string s;
    std::cin >> s;

    std::vector<int> positions;
    positions.push_back(-1);
    for (size_t i = 0; i < s.length(); ++i) {
        if (s[i] == '(' || s[i] == ')') {
            positions.push_back(i);
        }
    }

    int totalWordsInBraces = 0;
    int maxWordLength = 0;

    int i = 1;
    std::string outsideStr;

    while (i < static_cast<int>(positions.size()) - 1) {
        int startIdx = positions[i];
        int endIdx = positions[i + 1];
        std::string insideStr = s.substr(startIdx + 1, endIdx - startIdx - 1);
        int countWordsIn = countWords(insideStr);
        totalWordsInBraces += countWordsIn;

        int prevIdx = positions[i - 1];
        int outsidePartStart = prevIdx + 1;
        int outsidePartEnd = startIdx;
        if (outsidePartEnd > outsidePartStart) {
            outsideStr += "_" + s.substr(outsidePartStart, outsidePartEnd - outsidePartStart);
        }
        i += 2;
    }

    int lastIdx = positions.back();
    if (lastIdx + 1 < static_cast<int>(s.length())) {
        outsideStr += "_" + s.substr(lastIdx + 1);
    }

    // Replace underscores with spaces
    std::replace(outsideStr.begin(), outsideStr.end(), '_', ' ');
    // Trim leading and trailing spaces
    size_t start = outsideStr.find_first_not_of(' ');
    size_t end = outsideStr.find_last_not_of(' ');
    if (start != std::string::npos && end != std::string::npos) {
        outsideStr = outsideStr.substr(start, end - start + 1);
    } else {
        outsideStr.clear();
    }
    // Replace multiple spaces with a single space
    std::string cleaned;
    bool inSpace = false;
    for (char c : outsideStr) {
        if (isspace(c)) {
            if (!inSpace) {
                cleaned += ' ';
                inSpace = true;
            }
        } else {
            cleaned += c;
            inSpace = false;
        }
    }
    outsideStr = cleaned;

    // Split outside words
    std::istringstream iss(outsideStr);
    std::string word;
    while (iss >> word) {
        if (static_cast<int>(word.length()) > maxWordLength) {
            maxWordLength = word.length();
        }
    }

    std::cout << maxWordLength << " " << totalWordsInBraces;
    return 0;
}

